// Matrizes curriculares oficiais SEED-PR para Educação Profissional Técnica
// de Nível Médio, forma concomitante intercomplementar, ano de implantação 2026
// (Instrução Normativa Conjunta n.º 005/2026 - DEDUC/DPGE/SEED, versão finalizada
// de abril/2026). Fonte: documento oficial fornecido pela escola.
//
// [REGERADO] Reextraído do zero com um parser corrigido e validado item a item
// contra os totais impressos no PDF (FGB, Aprofundamento, Itinerário Formativo
// Técnico Profissional e Parte Diversificada todos batendo 100% com o
// documento oficial). Substitui a versão anterior, que tinha nomes de
// disciplina cortados e rótulos de categoria (ex: "Aprofundamento", "If")
// vazando dentro do nome — resultado de um bug de parsing de PDF que também
// afetava a extração anterior; agora corrigido.
//
// Diferente da versão anterior, aqui as categorias vêm separadas de verdade
// (FGB / IFA — Aprofundamento / APF — Itinerário Formativo Técnico
// Profissional / PD — Parte Diversificada), em vez de tudo agrupado em "IFP".
//
// Usa só a série de códigos "na forma concomitante intercomplementar" com
// Ano de Implantação 2026 (o documento também traz uma série de códigos mais
// antiga, 2318-2399, provavelmente uma matriz de transição para alunos que já
// estavam cursando antes de 2026 — mantido o mesmo critério de exclusão da
// versão anterior).
//
// Nota: o documento traz DOIS cursos "Técnico em Inteligência Artificial" com
// códigos e grades completamente diferentes (4817 e 4706). Mantido só o 4817
// (mesma numeração dos outros 17 cursos originais); o 4706 foi propositalmente
// deixado de fora — se precisar dele depois, é só pedir.
//
// Eixo tecnológico preenchido a partir de CURSOS_TECNICOS_POR_EIXO
// (cursos-tecnicos-cnct.ts) por correspondência de nome. "Técnico em
// Inteligência Artificial" não consta no CNCT 4ª edição ainda, então ficou
// "?" — preencher manualmente se/quando a SEED-PR classificar oficialmente.
//
// Língua Espanhola (Parte Diversificada, 4h/semana) é de matrícula facultativa
// para o aluno — incluída aqui como item não-obrigatório.

// [ATUALIZADO] Agora cobre as DUAS formas de oferta técnica da SEED-PR:
// - "concomitante_intercomplementar" (IN 005/2026, 27 cursos, códigos 4700-4817)
// - "integrada" (IN 001/2026, 35 cursos, códigos 2501-2542)
// Um mesmo nome de curso pode existir nas duas formas com grades DIFERENTES
// (ex: "Técnico em Farmácia" integrada x concomitante) — por isso cada
// template carrega `formaOferta`, e o casamento automático em cursos/index.tsx
// agora filtra por formaOferta do curso além do nome, evitando ambiguidade.

export interface ItemMatrizTecnica {
  nome: string;
  categoria: "FGB" | "IFA" | "APF" | "PD";
  cargaHorariaSemanal: number;
  obrigatoria: boolean;
}

export interface MatrizTecnicaTemplate {
  codigo: string;
  curso: string;
  eixo: string;
  formaOferta: "integrada" | "concomitante_intercomplementar";
  series: { serieAno: string; itens: ItemMatrizTecnica[] }[];
}

